//! 🔀️ Unique converted UI argument owners merge without cloning keys, values or whole objects.
use super::*;
/// 🧳️ Private original vectors retain every displaced owner until its exact funded retirement completes.
pub struct OriginalUiArgumentsMerge{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,args:ManuallyDrop<Option<DslValue>>,input:ManuallyDrop<Option<DslValue>>,current:ManuallyDrop<Option<(String,DslValue)>>,displaced:ManuallyDrop<Option<DslValue>>,retirement:RetainedCloneClose,index:usize,scan:usize,offset:usize,phase:u8,closing:bool,taken:bool}
const STATE:usize=size_of::<(usize,usize,usize,u8)>();
impl OriginalUiArgumentsMerge{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()+4*size_of::<Option<DslValue>>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 /// 📥️ Only original private converted values transfer; the corresponding UI arena roots have already returned.
 pub fn admit(args:&mut Option<DslValue>,input:&mut Option<DslValue>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{for source in [&*args,&*input]{if matches!(source,Some(DslValue::Object(rows))if rows.len()>UI_VALUE_MAX_ITEMS){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"UI argument merge exceeds its declared original collection extent").into())}}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::birth_demands();admit_original_construction(cx,output,original(d),|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::write(Box::new_uninit(),Self{binding,decoder,body,args:ManuallyDrop::new(args.take()),input:ManuallyDrop::new(input.take()),current:ManuallyDrop::new(None),displaced:ManuallyDrop::new(None),retirement:Default::default(),index:0,scan:0,offset:0,phase:0,closing:false,taken:false}),receipt(d)))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn objects(&self)->Result<(&Vec<(String,DslValue)>,&Vec<(String,DslValue)>),ValueError>{match(self.args.as_ref(),self.input.as_ref()){(Some(DslValue::Object(args)),Some(DslValue::Object(input)))=>Ok((args,input)),_=>Err(invalid())}}
 fn private_close(&self)->bool{!self.retirement.is_empty()||match self.phase{6=>self.current.is_some()||self.displaced.is_some(),8=>self.input.is_some(),10=>self.args.is_some(),_=>false}}
 fn private_demands(&self)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(self.body)}match self.phase{6 if self.displaced.is_some()=>self.retirement.next_owner_demands::<DslValue>(true,&None,self.body),6 if self.current.is_some()=>self.retirement.next_owner_demands::<(String,DslValue)>(true,&None,self.body),8 if self.input.is_some()=>self.retirement.next_owner_demands::<DslValue>(true,&None,self.body),10 if self.args.is_some()=>self.retirement.next_owner_demands::<DslValue>(true,&None,self.body),_=>Err(invalid())}}
 pub fn demands(&self)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands()}if self.private_close(){return self.private_demands()}let mut d=match self.phase{0|6|8|10=>header::<(Option<DslValue>,Option<DslValue>,usize,usize,usize,u8)>(),1=>{let(args,input)=self.objects()?;let target=args.len().checked_add(input.len()).ok_or_else(invalid)?;if args.capacity()>=target{header::<u8>()}else{RetirementDemand{copy_bytes:args.len().checked_mul(size_of::<(String,DslValue)>()).ok_or_else(invalid)?+2*size_of::<Vec<(String,DslValue)>>(),capacity_bytes:target.checked_mul(size_of::<(String,DslValue)>()).ok_or_else(invalid)?,release_bytes:args.capacity().checked_mul(size_of::<(String,DslValue)>()).ok_or_else(invalid)?,depth:1}}},2=>header::<((String,DslValue),(String,DslValue),Option<(String,DslValue)>)>(),3=>{let(args,_)=self.objects()?;let count=if let Some((key,_))=args.get(self.scan){let original=&self.current.as_ref().ok_or_else(invalid)?.0;if key.len()==original.len(){(key.len()-self.offset).min(64)}else{0}}else{0};RetirementDemand{copy_bytes:2*count,depth:1,..Default::default()}},4=>header::<(DslValue,DslValue,DslValue,DslValue,Option<DslValue>)>(),5=>header::<((String,DslValue),(String,DslValue))>(),9=>return self.take_demands(),_=>return Err(invalid())};d.copy_bytes=d.copy_bytes.checked_add(STATE).ok_or_else(invalid)?;Ok(d)}
 pub fn ready(&self)->bool{!self.closing&&!self.taken&&self.phase==9}
 /// 🔎️ Each original turn moves one header, compares at most sixty-four key bytes, or closes one actual displaced owner.
 pub fn advance(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing||self.taken{return Err(invalid().into())}if self.ready(){return Ok(true)}let d=self.demands()?;if self.private_close(){close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.select(self.body)?.step(g)}if self.phase==6&&self.displaced.is_some(){return Ok(self.retirement.begin_granted(&mut self.displaced,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.phase==6&&self.current.is_some(){return Ok(self.retirement.begin_granted(&mut self.current,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.phase==8{return Ok(self.retirement.begin_granted(&mut self.input,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}Ok(self.retirement.begin_granted(&mut self.args,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))})?;return Ok(false)}let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{match self.phase{
 0=>{if self.input.is_none(){self.phase=9;}else if self.args.is_none(){*self.args=self.input.take();self.phase=9;}else if matches!((&*self.args,&*self.input),(Some(DslValue::Object(_)),Some(DslValue::Object(_)))){self.phase=1;}else{self.phase=10;}},
 1=>{let(Some(DslValue::Object(args)),Some(DslValue::Object(input)))=(&mut *self.args,&*self.input)else{return Err(invalid())};let target=args.len().checked_add(input.len()).ok_or_else(invalid)?;if args.capacity()<target{args.try_reserve_exact(target-args.len()).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"native UI merge object backing refused"))?;}self.phase=2;},
 2=>{let Some(DslValue::Object(input))=self.input.as_mut()else{return Err(invalid())};if self.index==input.len(){self.phase=8;}else{*self.current=Some(std::mem::replace(&mut input[self.index],(String::new(),DslValue::Null)));self.scan=0;self.offset=0;self.phase=3;}},
 3=>{let(args,_)=self.objects()?;if let Some((key,_))=args.get(self.scan){let original=&self.current.as_ref().ok_or_else(invalid)?.0;let count=if key.len()==original.len(){(key.len()-self.offset).min(64)}else{0};let equal=key.len()==original.len()&&key.as_bytes()[self.offset..self.offset+count]==original.as_bytes()[self.offset..self.offset+count];if equal&&self.offset+count==key.len(){self.phase=4;}else if equal{self.offset+=count;}else{self.scan+=1;self.offset=0;}}else{self.phase=5;}},
 4=>{let Some(DslValue::Object(args))=self.args.as_mut()else{return Err(invalid())};let current=self.current.as_mut().ok_or_else(invalid)?;let value=std::mem::replace(&mut current.1,DslValue::Null);*self.displaced=Some(std::mem::replace(&mut args[self.scan].1,value));self.phase=6;},
 5=>{let Some(DslValue::Object(args))=self.args.as_mut()else{return Err(invalid())};if args.len()==args.capacity(){return Err(invalid())}args.push(self.current.take().ok_or_else(invalid)?);self.phase=6;},
 6=>{self.index+=1;self.scan=0;self.offset=0;self.phase=2;},8=>self.phase=9,10=>{*self.args=self.input.take();self.phase=9;},_=>return Err(invalid())}Ok(((),receipt(d)))})?;Ok(self.ready())}
 pub fn take_demands(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid())}Ok(header::<(Option<DslValue>,Option<DslValue>,bool)>())}
 /// 🤝️ A missing argument remains missing; every present result moves its original final allocation into the receiving slot.
 pub fn take_into(&mut self,output:&mut Option<DslValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if output.is_some(){return Err(invalid().into())}let d=self.take_demands()?;let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{*output=self.args.take();self.taken=true;Ok(((),receipt(d)))})}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.current.is_some(){return self.retirement.next_owner_demands::<(String,DslValue)>(true,&None,self.body)}if self.displaced.is_some(){return self.retirement.next_owner_demands::<DslValue>(true,&None,self.body)}if self.args.is_some(){return self.retirement.next_owner_demands::<DslValue>(true,&None,self.body)}if self.input.is_some(){return self.retirement.next_owner_demands::<DslValue>(true,&None,self.body)}Ok(Default::default())}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands()?;close_original_retained_step(cx,d,|g|{if !self.closing{self.closing=true;return Ok(RetainedCloneStep::Progress(receipt(d)))}if !self.retirement.is_empty(){return self.retirement.select(self.body)?.step(g)}if self.current.is_some(){return Ok(self.retirement.begin_granted(&mut self.current,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.displaced.is_some(){return Ok(self.retirement.begin_granted(&mut self.displaced,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.args.is_some(){return Ok(self.retirement.begin_granted(&mut self.args,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.input.is_some(){return Ok(self.retirement.begin_granted(&mut self.input,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}Ok(RetainedCloneStep::Complete(Default::default()))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{(self.closing||self.taken)&&self.args.is_none()&&self.input.is_none()&&self.current.is_none()&&self.displaced.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalUiArgumentsMerge{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native UI merge must transfer or close every private original owner")}}
